const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function evidenceContent(entry){
 const rows=(entry.evidence||[]).map(e=>`<tr><th scope="row">${escape(e.feature)}</th><td><strong>${escape(e.certainty)}</strong><br>${escape(e.basis)}</td></tr>`).join('');
 const sources=(entry.sources||[]).map((url,i)=>`<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${i?'Referencia '+(i+1):'Publicación principal'}<small>${escape(new URL(url).hostname)}</small></a>`).join('');
 return `<p class="eyebrow">ARQUEOLOGÍA · LUGAR ${entry.number}</p><h2>${escape(entry.name)}</h2><p>${escape(entry.history)}</p><div class="fact-banner"><p><strong>${escape(entry.period)}</strong><br>${escape(entry.look)}</p></div><h3>Qué sabemos, qué interpretamos</h3><table class="evidence-table"><thead><tr><th>Elemento</th><th>Evidencia y alcance</th></tr></thead><tbody>${rows}</tbody></table><h3>Cómo leer las vistas</h3><p>Actual sitúa los restos en el paisaje contemporáneo. ${entry.id==='circo'?'Corte despeja visualmente las protecciones contemporáneas y muestra un perfil explicativo del terreno.':entry.id==='necropolis'?'Corte abre las losas y el relleno didáctico de las sepulturas o la cubierta de roca del hipogeo seleccionado.':'Corte desplaza una parte del suelo y de la construcción superior para observarlos.'} Histórica muestra la fase o interpretación indicada en la ficha; las restituciones de alzados, cubiertas o partes perdidas se identifican y pueden ocultarse cuando están agrupadas como hipótesis.</p><p class="model-note">El recorte y sus bandas de suelo son recursos de visualización; no reproducen un perfil estratigráfico medido. Las cotas de enterramiento, las texturas de desgaste y los detalles sin dimensiones publicadas son aproximaciones. Cada ficha precisa los límites de su reconstrucción.</p><div class="sources-list">${sources}</div>`;
}
export function renderArchaeologyPanel({entry,controller,ready,onFocus,presentationMode}){
 const $=id=>document.getElementById(id),panel=$('archaeology-panel');panel.hidden=!entry?.archaeological||entry.id==='forum-plaza';
 document.body.classList.toggle('archaeology-mode',!panel.hidden);if(panel.hidden)return;
 const state=controller?.state,site=state?.site,focus=state?.focus,isCirco=entry.id==='circo',isNecropolis=entry.id==='necropolis',isCavity=focus?.id==='hipogeos';
 $('cut-opening-label').textContent=isCirco?'Despejar protecciones actuales':isNecropolis?(isCavity?'Abrir la cubierta de roca':'Abrir losas y relleno'):'Levantar suelo y cubierta';$('cut-cover-label').textContent=isCirco?'Ver protecciones actuales':isNecropolis?(isCavity?'Ver cubierta retirada':'Ver losas retiradas'):'Ver bloque desplazado';
 $('cut-opening').setAttribute('aria-label',isCirco?'Despejar las protecciones contemporáneas':isNecropolis?(isCavity?'Apertura de la cubierta de roca':'Apertura de losas y relleno'):'Apertura del corte arqueológico');
 const mode=state?.mode||(isCirco?presentationMode:null)||(['portic','domus','circo','necropolis'].includes(entry.id)?'current':entry.cutEnabled?'cut':'current'),hasCut=ready?!!(focus?.cut||site?.cut):entry.cutEnabled;
 const focusList=site?.focuses||entry.secondaryLocations?.length&&[{id:'cementerio',label:'Necrópolis'},{id:'hipogeos',label:'Hipogeos'}]||[];
 $('archaeology-focuses').hidden=focusList.length<2;
 $('archaeology-focuses').innerHTML=focusList.map(f=>`<button data-arch-focus="${escape(f.id)}" aria-pressed="${state?.focusId===f.id}">${escape(f.label||f.name)}</button>`).join('');
 $('archaeology-focuses').querySelectorAll('button').forEach(button=>{button.disabled=!ready;button.onclick=()=>onFocus(button.dataset.archFocus);});
 panel.querySelectorAll('[data-arch-mode]').forEach(button=>{const cut=button.dataset.archMode==='cut';button.hidden=cut?(!hasCut||isCirco&&mode==='historical'):isCirco;if(cut)button.textContent=isCirco?'Leer corte de la puerta':'Corte';button.disabled=!ready;button.setAttribute('aria-pressed',String(button.dataset.archMode===mode));});
 $('excavation-opening').hidden=mode!=='cut';$('cut-opening').disabled=!ready;$('cut-opening').value=Math.round((state?.opening??1)*100);$('cut-opening-value').textContent=$('cut-opening').value+' %';
 $('show-cut-cover').checked=state?.coverShown??true;$('show-cut-cover').disabled=!ready;
 $('archaeology-historical').hidden=mode!=='historical';$('show-hypotheses').checked=state?.hypotheses??true;$('show-hypotheses').disabled=!ready;
 const roofs=focus?.roofs||site?.roofs||focus?.cutObjects||site?.cutObjects||[];$('historic-roof-option').hidden=!roofs.length&&!focus?.roofControl&&!site?.roofControl;$('historic-roof').checked=state?.roofOpen??true;$('historic-roof-label').textContent=isNecropolis?(isCavity?'Abrir cubierta de roca':'Abrir las losas'):'Abrir cubierta';
 const interpretiveCavity=isCavity;
 $('archaeology-period').textContent=mode==='historical'?(focus?.period||focus?.reconstruction?.userData.period||entry.period):mode==='cut'?(interpretiveCavity?'Hipogeos · sección interpretativa':isCirco?'Sección de lectura · restos y niveles':'Restos conservados · sección del terreno'):['portic','domus'].includes(entry.id)?'Espacio arqueológico musealizado':entry.openExcavation?'Restos conservados · excavación abierta':interpretiveCavity?'Hipogeos · exterior interpretado':'Restos en su contexto actual';
 const extra=focus?.interpretation||site?.cutNote||entry.cutNote||'';
 $('archaeology-note').textContent=!ready?'La vista 3D requiere WebGL. Puedes consultar el mapa, las evidencias y todas las fuentes.':mode==='historical'?(focus?.interpretation||(isCirco?'El trazado aproxima el antiguo circo bajo la ciudad. Graderío de madera, metas, salidas y alzados propuestos pueden ocultarse con Mostrar hipótesis.':'Esta vista muestra la fase o interpretación indicada. Los alzados se restituyen; consulta sus evidencias y las hipótesis opcionales.')):(mode==='cut'?(isCirco?'Desliza para hacer transparentes la tarima y las protecciones actuales. ':isNecropolis?(isCavity?'Desliza para retirar la cubierta rocosa y leer el interior. ':'Desliza para separar las losas y descubrir la construcción de las fosas. '):'Desliza para abrir o cerrar el corte. El bloque desplazado sitúa los restos bajo la superficie actual. ')+extra:(interpretiveCavity?extra:isNecropolis?'Explora las losas, la fábrica de las sepulturas y su relación con el acceso al castillo. El segundo sector muestra las cavidades de la ladera.':['portic','domus'].includes(entry.id)?(entry.id==='domus'?'Descubre el patio, las pinturas y las estancias desde las paradas. Corte abre la ciudad actual; Histórica propone la casa durante su fase residencial.':'Explora la calzada y las estructuras desde las paradas de la visita. Corte levanta la cobertura contemporánea; Histórica muestra una interpretación de la fase altoimperial.'):entry.id==='diana'?'La identificación como templo y su cronología siguen en discusión.':entry.openExcavation?'La puerta se conserva bajo la rasante de la plaza; aquí la excavación ya está abierta.':'Abre Corte para observar las estructuras que quedan bajo la superficie.'));
}
